import React, { useEffect, useState, useCallback } from "react";
import api from "../api";
import io from "socket.io-client";

type Comment = {
  _id: string;
  body: string;
  createdAt: string;
  author?: {
    email?: string;
  } | null;
};

type Ticket = {
  _id: string;
  title: string;
  description?: string;
  status: "Open" | "In Progress" | "Closed";
  category: "Billing" | "Technical" | "General";
  priority: "Low" | "Medium" | "High";
  createdBy: any;
  assignee: any;
  createdAt: string;
  comments?: Comment[];
};

type TicketWithComments = Ticket & {
  comments?: Comment[];
};

interface AgentDashboardProps {
  name: string;
}

const AgentDashboard: React.FC<AgentDashboardProps> = ({ name }) => {
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [socket, setSocket] = useState<any>(null);
  const [selectedTicket, setSelectedTicket] = useState<Ticket | null>(null);

  const [editPriority, setEditPriority] = useState<"Low" | "Medium" | "High">(
    "Medium"
  );
  const [editStatus, setEditStatus] = useState<
    "Open" | "In Progress" | "Closed"
  >("Open");

  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState("");

  // 1. Fetch assigned tickets
  const fetchTickets = useCallback(async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      const data = res.data;
      console.log("AGENT fetchTickets result", data);

      setTickets(data);

      // keep open modal in sync
      setSelectedTicket((prev) => {
        if (!prev) return prev;
        const updated = data.find((t) => t._id === prev._id);
        return updated || prev;
      });
    } catch (err) {
      console.error("AGENT Error fetching tickets:", err);
    }
  }, []);

  // 2. Create socket connection
  useEffect(() => {
    const s = io("http://localhost:5050", {
      withCredentials: true,
    } as any);

    s.on("connect", () => {
      console.log("AGENT socket connected:", s.id);
    });

    s.on("connect_error", (err: any) => {
      console.error("AGENT socket connect_error:", err.message);
    });

    setSocket(s);

    return () => {
      console.log("AGENT socket disconnect");
      s.disconnect();
    };
  }, []);

  // 3. Subscribe to socket updates
  useEffect(() => {
    if (!socket) return;

    const handleUpdated = (data: any) => {
      console.log("AGENT got ticketUpdated", data?._id);
      fetchTickets();
    };
    const handleCreated = (data: any) => {
      console.log("AGENT got ticketCreated", data?._id);
      fetchTickets();
    };
    const handleDeleted = (id: any) => {
      console.log("AGENT got ticketDeleted", id);
      fetchTickets();
    };

    socket.on("ticketUpdated", handleUpdated);
    socket.on("ticketCreated", handleCreated);
    socket.on("ticketDeleted", handleDeleted);

    return () => {
      socket.off("ticketUpdated", handleUpdated);
      socket.off("ticketCreated", handleCreated);
      socket.off("ticketDeleted", handleDeleted);
    };
  }, [socket, fetchTickets]);

  // Initial load
  useEffect(() => {
    fetchTickets();
  }, [fetchTickets]);

  // 4. When user clicks a ticket, sync the editable fields
  const handleSelectTicket = async (t: Ticket) => {
    try {
      const res = await api.get(`/tickets/${t._id}`);
      const fullTicket = res.data as TicketWithComments;

      console.log("AGENT loaded full ticket", fullTicket);

      setSelectedTicket(fullTicket);
      setComments(fullTicket.comments || []);
      setEditPriority(fullTicket.priority);
      setEditStatus(fullTicket.status);
    } catch (err) {
      console.error("Failed to load ticket details:", err);
      alert("Failed to load ticket details");
    }
  };

  // 5. Save changes (status + priority)
  const handleUpdate = async () => {
    if (!selectedTicket) return;

    try {
      console.log(
        "AGENT saving ticket",
        selectedTicket._id,
        "status:",
        editStatus,
        "priority:",
        editPriority
      );

      const res = await api.patch(`/tickets/${selectedTicket._id}`, {
        priority: editPriority,
        status: editStatus,
      });

      const updated = res.data as Ticket;
      console.log("AGENT update response:", updated);

      // Update tickets array
      setTickets((prev: Ticket[]) =>
        prev.map((t: Ticket) => (t._id === updated._id ? updated : t))
      );

      // Optionally keep it open with updated data instead of closing:
      setSelectedTicket(updated);
    } catch (err: any) {
      console.error("Failed to update ticket:", err?.response || err);
      alert(
        err?.response?.data?.message ||
          "Failed to update ticket (check console)"
      );
    }
  };

  const handleAddComment = async () => {
    if (!selectedTicket || !newComment.trim()) return;

    try {
      const res = await api.post(`/tickets/${selectedTicket._id}/comments`, {
        body: newComment,
      });

      const updated = res.data as TicketWithComments;
      console.log("AGENT added comment:", updated);

      setComments(updated.comments || []);
      setNewComment("");
    } catch (err) {
      console.error("Failed to add comment:", err);
      alert("Failed to add comment");
    }
  };

  return (
    <div>
      <h2>Agent Dashboard</h2>
      <p>Welcome, {name}!</p>

      <h3>Assigned Tickets</h3>

      {tickets.length === 0 ? (
        <p>No assigned tickets.</p>
      ) : (
        <ul>
          {tickets.map((t) => (
            <li
              key={t._id}
              style={{ cursor: "pointer" }}
              onClick={() => handleSelectTicket(t)}
            >
              {t.title}
            </li>
          ))}
        </ul>
      )}

      {selectedTicket && (
        <div style={{ marginTop: "20px" }}>
          <h3>Ticket Details</h3>

          <p>
            <strong>Title:</strong> {selectedTicket.title}
          </p>
          <p>
            <strong>Description:</strong> {selectedTicket.description}
          </p>
          <p>
            <strong>Category:</strong> {selectedTicket.category}
          </p>

          <p>
            <strong>Priority:</strong>
            <select
              value={editPriority}
              onChange={(e) =>
                setEditPriority(e.target.value as "Low" | "Medium" | "High")
              }
              style={{ marginLeft: "10px" }}
            >
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
            </select>
          </p>

          <p>
            <strong>Status:</strong>
            <select
              value={editStatus}
              onChange={(e) =>
                setEditStatus(
                  e.target.value as "Open" | "In Progress" | "Closed"
                )
              }
              style={{ marginLeft: "10px" }}
            >
              <option value="Open">Open</option>
              <option value="In Progress">In Progress</option>
              <option value="Closed">Closed</option>
            </select>
          </p>

          <p>
            <strong>Created:</strong>{" "}
            {new Date(selectedTicket.createdAt).toLocaleString()}
          </p>

          <button onClick={handleUpdate} style={{ marginRight: "10px" }}>
            Save Changes
          </button>

          {/* COMMENTS */}
          <h3>Comments</h3>

          <ul>
            {comments.map((c, i) => (
              <li key={i} style={{ marginBottom: "10px" }}>
                <strong>{c.author?.email || "Unknown user"}:</strong>
                <br />
                {c.body}
                <br />
                <small>{new Date(c.createdAt).toLocaleString()}</small>
              </li>
            ))}
          </ul>

          <textarea
            placeholder="Write a comment..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            style={{ width: "300px", height: "80px" }}
          />

          <br />

          <button onClick={handleAddComment}>Add Comment</button>
          <button onClick={() => setSelectedTicket(null)}>Close</button>
        </div>
      )}
    </div>
  );
};

export default AgentDashboard;
